#!/bin/bash
# Public reproduction: does aligning speculators' MTP finetune with vLLM's MTP proposer
# (TTT attention + post-final-norm hidden states) matter? Qwen/Qwen3.5-4B, its native MTP
# head, Alpaca prompts with responses regenerated by the model itself.
#   A = upstream FastMTP-style forward (SPECULATORS_MTP_TTT=0, POSTNORM=0)
#   B = vLLM-aligned forward          (SPECULATORS_MTP_TTT=1, POSTNORM=1)
# Same data / steps / lr / step weights for both; only the forward differs.
# Each stage leaves a marker in state/, so a rerun resumes after the last finished stage.
#   python make_alpaca_prompts.py && tmux new -d -s mtprepro 'bash mtp_repro_pipeline.sh 2>&1 | tee logs/pipeline.log'
set -euo pipefail
cd "$(dirname "$0")"
mkdir -p state logs ckpt results
GPU=${GPU:-1}
SPEC=${SPECULATORS_SRC:-$HOME/speculators}  # speculators checkout with patches/speculators-mtp-ttt.patch applied
SPEC_BIN=${SPEC_ENV:-$HOME/envs/speculators}/bin  # env with speculators + vLLM (hidden-state server)
export PATH=$SPEC_BIN:$PATH PYTHONPATH=$SPEC/src HF_HUB_OFFLINE=${HF_HUB_OFFLINE:-0}
export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
MODEL=Qwen/Qwen3.5-4B
MAX_STEPS=${MAX_STEPS:-800}

log() { echo "[$(date +%H:%M:%S)] $*"; }
done_() { [ -f state/$1 ]; }
mark() { touch state/$1; }

wait_gpu_free() {
  for _ in $(seq 120); do
    [ "$(nvidia-smi --query-gpu=memory.used --format=csv,noheader,nounits -i $GPU)" -lt 1000 ] && return 0
    sleep 5
  done
  log "GPU $GPU still busy"; return 1
}
wait_health() {  # <port> <tmux session>
  for _ in $(seq 240); do
    curl -sf -m2 localhost:$1/health >/dev/null && return 0
    tmux has-session -t $2 2>/dev/null || { log "server $2 died"; return 1; }
    sleep 5
  done
  return 1
}
stop() { tmux kill-session -t $1 2>/dev/null || true; sleep 5; }

# 1+2. regenerate responses with the model itself, then render + tokenize
if ! done_ data; then
  wait_gpu_free
  tmux new -d -s mtpgen "CUDA_VISIBLE_DEVICES=$GPU PATH=$PATH HF_HUB_OFFLINE=$HF_HUB_OFFLINE vllm serve $MODEL \
    --port 8000 --max-model-len 16384 --gpu-memory-utilization 0.9 --language-model-only \
    --enable-prefix-caching --reasoning-parser qwen3 2>&1 | tee logs/gen_server.log"
  wait_health 8000 mtpgen
  log "regenerating responses"
  python -m speculators regenerate-responses --endpoint http://127.0.0.1:8000/v1/chat/completions \
    --dataset data/alpaca_prompts_8k.jsonl --concurrency 96 --max-tokens 4096 \
    --sampling-params '{"temperature": 0.6, "top_p": 0.95, "top_k": 20, "seed": 0}' \
    --outfile data/alpaca_regen_qwen35_4b.jsonl --resume 2>&1 | tail -5
  log "prepare-data"
  python -m speculators prepare-data --model $MODEL --data data/alpaca_regen_qwen35_4b.jsonl \
    --output data/out --seq-length 12288 --render-endpoint http://localhost:8000 --overwrite 2>&1 | tail -5
  stop mtpgen
  mark data
fi

start_hs() {  # hidden-state server for training (last layer only, as in train_mtp.sh)
  stop mtphs; wait_gpu_free
  tmux new -d -s mtphs "cd $SPEC && CUDA_VISIBLE_DEVICES=$GPU PATH=$PATH HF_HUB_OFFLINE=$HF_HUB_OFFLINE python scripts/launch_vllm.py $MODEL \
    --target-layer-ids 32 -- --port 8000 --language-model-only --dtype bfloat16 --max-model-len 16384 \
    --no-enable-prefix-caching --mamba-cache-dtype bfloat16 --mamba-ssm-cache-dtype bfloat16 \
    --gpu-memory-utilization 0.45 --max-num-seqs 16 --enforce-eager 2>&1 | tee $PWD/logs/hs_server.log"
  wait_health 8000 mtphs
}

train() {  # <name> <ttt> <postnorm>
  done_ train_$1 && return 0
  start_hs
  log "train $1 (TTT=$2 POSTNORM=$3)"
  rm -rf ckpt/mtp_$1
  SPECULATORS_MTP_TTT=$2 SPECULATORS_MTP_POSTNORM=$3 CUDA_VISIBLE_DEVICES=$GPU \
  torchrun --standalone --nproc_per_node 1 -m speculators.train \
    --speculator-type mtp --verifier-name-or-path $MODEL --trust-remote-code \
    --data-path data/out --train-data-ratio 0.98 \
    --vllm-endpoint http://localhost:8000/v1 --on-missing generate \
    --save-path ckpt/mtp_$1 --target-layer-ids 32 \
    --num-speculative-steps 8 --step-weight-beta 0.8 --total-seq-len 12288 \
    --lr 1e-5 --scheduler-type cosine --scheduler-warmup-ratio 0.02 --epochs 1 \
    --checkpoint-freq 0.25 --gradient-checkpointing --log-freq 1 --max-steps $MAX_STEPS \
    > logs/train_$1.log 2>&1
  stop mtphs
  mark train_$1
}
train A_fastmtp 0 0
train B_aligned 1 1

# stitch the last checkpoint of each run back into the verifier
for name in A_fastmtp B_aligned; do
  done_ stitch_$name && continue
  last=$(ls -d ckpt/mtp_$name/epoch0_end ckpt/mtp_$name/0 2>/dev/null | head -1)
  log "stitch $name from $last"
  python -m speculators stitch-mtp "$last" $MODEL --output-path ckpt/qwen35_4b_mtp_$name > logs/stitch_$name.log 2>&1
  mark stitch_$name
done

# evaluate native / A / B: stock spec-decode kernels, MTP K=5, Spec-Bench, c=32
for spec in native:$MODEL A_fastmtp:$PWD/ckpt/qwen35_4b_mtp_A_fastmtp B_aligned:$PWD/ckpt/qwen35_4b_mtp_B_aligned; do
  name=${spec%%:*}; path=${spec#*:}
  done_ eval_$name && continue
  wait_gpu_free
  log "eval $name"
  MODEL_PATH=$path NAME_PREFIX=mtp_$name K=5 REPLAY=0 GPU=$GPU RUNS="32:480" \
    bash ../bench/bench_one.sh | grep -E "Output token|Mean TPOT|accept" | tee results/eval_$name.txt
  mark eval_$name
done
log PIPELINE_DONE
